      answer: "-7*sqrt(3)*exp(1/2)/8",
      timeLimit: 300,
      tags: ["chain-rule","higher-derivative"],
      hints: ["令 u = sin x，h = e^u：h‴ = e^u(u′³ + 3u′u″ + u‴)。","在 π/6 先把 u、u′、u″、u‴ 四個值列出來。"],
      solution: "u = 1/2、u′ = √3/2、u″ = −1/2、u‴ = −√3/2；括號 = 3√3/8 − 3√3/4 − √3/2 = −7√3/8，乘 e^{1/2}。",
      solutionSteps: ["h′ = e^u u′，h″ = e^u(u′² + u″)，h‴ = e^u(u′³ + 3u′u″ + u‴)。","x = π/6：u = 1/2，u′ = √3/2，u″ = −1/2，u‴ = −√3/2。","u′³ + 3u′u″ + u‴ = 3√3/8 − 6√3/8 − 4√3/8 = −7√3/8。","答案 −7√3 e^{1/2}/8。"],
