      answerKind: "text",
      prompt: "\\sum_{n=1}^{\\infty}\\frac{(-1)^{n+1}}{\\sqrt n}\\text{ 條件收斂。把它重排成「兩個正項配一個負項」：}1+\\frac{1}{\\sqrt3}-\\frac{1}{\\sqrt2}+\\frac{1}{\\sqrt5}+\\frac{1}{\\sqrt7}-\\frac{1}{\\sqrt4}+\\cdots\\text{。重排後的級數收斂還是發散？}",
