      solution: "第 k 組 = 1/√(4k−3) + 1/√(4k−1) − 1/√(2k)。大 k 時 ≈ 2/(2√k) − 1/(√2·√k) = (1 − 1/√2)/√k > 0。極限比較判別：各組和 Σ 1/√k 同斂散，發散到 +∞。分組不改變發散，所以重排後的級數發散 —— 不像 1/n 只是把和平移 (1/2)ln 2。",
      solutionSteps: ["第 k 組 = 1/√(4k−3) + 1/√(4k−1) − 1/√(2k)。","大 k 時 ≈ 2/(2√k) − 1/(√2·√k) = (1 − 1/√2)/√k > 0。","極限比較判別：各組和 Σ 1/√k 同斂散，發散到 +∞。分組不改變發散，所以重排後的級數發散 —— 不像 1/n 只是把和平移 (1/2)ln 2。"],
