      tags: ["exponential-series"],
      hints: ["項只跟 k = m + n 有關。固定 k，有幾組 (m, n)？","Σ_{k≥2} (k−1)/k! 拆成兩個 e 的級數。"],
      solution: "正項級數可以照對角線重新分組：k = m + n ≥ 2，每個 k 有 k − 1 組 (m, n)。和 = Σ_{k≥2} (k−1)/k! = Σ_{k≥2} 1/(k−1)! − Σ_{k≥2} 1/k! = (e − 1) − (e − 2) = 1。",
      solutionSteps: ["正項級數可以照對角線重新分組：k = m + n ≥ 2，每個 k 有 k − 1 組 (m, n)。","和 = Σ_{k≥2} (k−1)/k! = Σ_{k≥2} 1/(k−1)! − Σ_{k≥2} 1/k! = (e − 1) − (e − 2) = 1。"],
