      tags: ["log-series"],
      hints: ["一樣照 k = m + n 分組。","Σ (k−1)/(k 2^k) = Σ 1/2^k − Σ 1/(k 2^k)，第二個是 −ln(1 − x) 在 x = 1/2。"],
      solution: "正項，照 k = m + n ≥ 2 分組：每個 k 有 k − 1 組，和 = Σ_{k≥2} (k−1)/(k 2^k)。= Σ_{k≥2} 1/2^k − Σ_{k≥2} 1/(k 2^k) = 1/2 − (ln 2 − 1/2)。和 = 1 − ln 2。",
      solutionSteps: ["正項，照 k = m + n ≥ 2 分組：每個 k 有 k − 1 組，和 = Σ_{k≥2} (k−1)/(k 2^k)。","= Σ_{k≥2} 1/2^k − Σ_{k≥2} 1/(k 2^k) = 1/2 − (ln 2 − 1/2)。","和 = 1 − ln 2。"],
