      solutionSteps: ["正項可交換：範圍是 1 ≤ n ≤ k，固定 k 時 n 有 k 個值。","和 = Σ_{k≥1} k/3^k = (1/3)/(1 − 1/3)^2 = 3/4。","（直接算也行：內層 Σ_{k≥n} 1/3^k = (3/2)/3^n，再加總 = (3/2)(1/2) = 3/4。）"],
