      solution: "絕對值的雙重級數 Σ_{n≥2}Σ_{k≥2} k^{−n} = Σ_{k≥2} 1/(k(k−1)) = 1 < ∞，所以可以交換次序。固定 k：Σ_{n≥2} (−1/k)^n = (1/k^2)/(1 + 1/k) = 1/(k(k+1))。和 = Σ_{k≥2} 1/(k(k+1)) = 1/2。",
      solutionSteps: ["絕對值的雙重級數 Σ_{n≥2}Σ_{k≥2} k^{−n} = Σ_{k≥2} 1/(k(k−1)) = 1 < ∞，所以可以交換次序。","固定 k：Σ_{n≥2} (−1/k)^n = (1/k^2)/(1 + 1/k) = 1/(k(k+1))。","和 = Σ_{k≥2} 1/(k(k+1)) = 1/2。"],
