      solution: "正項，交換次序：和 = Σ_{k≥2} Σ_{n≥1} (1/k^2)^n/n = Σ_{k≥2} −ln(1 − 1/k^2)。= −ln ∏_{k≥2} (1 − 1/k^2)，而 ∏_{k=2}^{K} (1 − 1/k^2) = (K+1)/(2K) → 1/2。和 = −ln(1/2) = ln 2。",
