      solutionSteps: ["G(x) = 1/(1 − 2x) + 1/(1 − 3x)，|x| < 1/3 時收斂。","x = 1/6：1/(1 − 1/3) + 1/(1 − 1/2) = 3/2 + 2 = 7/2。"],
