      solution: "x^{10} 的係數 = 滿足 a + 2b + 5c = 10 的非負整數解 (a, b, c) 個數。c = 0：a + 2b = 10，b = 0..5，6 種；c = 1：a + 2b = 5，b = 0..2，3 種；c = 2：1 種。共 6 + 3 + 1 = 10。",
