      solutionSteps: ["由 Σ C(2n, n) t^n = 1/√(1 − 4t)：Σ_{n≥1} C(2n, n) x^n/n = ∫_0^x (1/√(1 − 4t) − 1)/t dt。","令 s = √(1 − 4t)：t = (1 − s^2)/4，被積式化成 −2/(1 + s) ds，積分 = 2 ln(2/(1 + √(1 − 4x)))。","x = 1/8：√(1/2) = 1/√2，2/(1 + 1/√2) = 2√2(√2 − 1) = 4 − 2√2。","和 = 2 ln(4 − 2√2) ≈ 0.3167。"],
