      prompt: "a_0=1,\\ a_n=a_{n-1}+2\\ (n\\ge1)\\text{。令 }G(x)=\\sum_{n=0}^{\\infty}a_nx^n\\text{，求 }G\\!\\left(\\frac12\\right)",
