      solutionSteps: ["Σ_{n≥1} a_n x^n = x Σ_{n≥1} a_{n−1}x^{n−1} + 2Σ_{n≥1} x^n，即 G − 1 = xG + 2x/(1 − x)。","解出 G(x) = (1 + x)/(1 − x)^2。","x = 1/2：(3/2)/(1/4) = 6。（對照：a_n = 2n + 1，Σ(2n+1)/2^n = 4 + 2 = 6。）"],
