      hints: ["生成函數 A(x) 的分母就是特徵多項式「反過來」：1 − 5x + 6x^2。","分子由前兩項決定。"],
      solution: "乘 x^{n+2} 加總：A − x = 5x A − 6x^2 A，所以 A(x) = x/(1 − 5x + 6x^2) = x/((1 − 2x)(1 − 3x))，|x| < 1/3。x = 1/7：(1/7)/(1 − 5/7 + 6/49) = (1/7)/(20/49) = 7/20。（對照：a_n = 3^n − 2^n，Σ(3/7)^n − Σ(2/7)^n = 7/4 − 7/5 = 7/20。）",
      solutionSteps: ["乘 x^{n+2} 加總：A − x = 5x A − 6x^2 A，所以 A(x) = x/(1 − 5x + 6x^2) = x/((1 − 2x)(1 − 3x))，|x| < 1/3。","x = 1/7：(1/7)/(1 − 5/7 + 6/49) = (1/7)/(20/49) = 7/20。","（對照：a_n = 3^n − 2^n，Σ(3/7)^n − Σ(2/7)^n = 7/4 − 7/5 = 7/20。）"],
