      solutionSteps: ["a_n = (2/π)∫_0^π cosh x cos(nx) dx = 2(−1)^n sinh π/(π(1 + n^2))，a_0/2 = sinh π/π。","cosh x 連續，周期延拓也連續，所以級數在 x = 0 收斂到 1：1 = (sinh π/π)[1 + 2 Σ (−1)^n/(1 + n^2)]。","Σ (−1)^n/(n^2 + 1) = (π/sinh π − 1)/2，所以所求 = (1 − π/sinh π)/2 ≈ 0.3640。"],
