      solutionSteps: ["sin^2 n/n^2 = (1/2)(1/n^2 − cos(2n)/n^2)。","0 ≤ θ ≤ 2π 時 Σ cos(nθ)/n^2 = π^2/6 − πθ/2 + θ^2/4。θ = 2：π^2/6 − π + 1。","和 = (1/2)[π^2/6 − (π^2/6 − π + 1)] = (π − 1)/2 ≈ 1.0708。（巧合：跟 Σ sin n/n 一樣大。）"],
