      solution: "Σ a_n 收斂：cos(2nπ/3) 部分和有界、n^{−1/3} 遞減到 0（Dirichlet）。a_n^3 = c_n/n，c_n 依序是 −1/8, −1/8, 1，平均 1/4 ≠ 0，所以 Σ a_n^3 像 (1/4)Σ 1/n 一樣發散。c_n − 1/4 依序是 −3/8, −3/8, 3/4 = (3/4)·cos(2nπ/3)，所以括號 → (3/4) Σ cos(2nπ/3)/n。Σ cos(2nπ/3)/n = −(1/2)(H_{3M} − H_M) 的極限 = −(ln 3)/2。答案 = (3/4)(−(ln 3)/2) = −(3/8) ln 3 ≈ −0.4120。",
      solutionSteps: ["Σ a_n 收斂：cos(2nπ/3) 部分和有界、n^{−1/3} 遞減到 0（Dirichlet）。","a_n^3 = c_n/n，c_n 依序是 −1/8, −1/8, 1，平均 1/4 ≠ 0，所以 Σ a_n^3 像 (1/4)Σ 1/n 一樣發散。","c_n − 1/4 依序是 −3/8, −3/8, 3/4 = (3/4)·cos(2nπ/3)，所以括號 → (3/4) Σ cos(2nπ/3)/n。","Σ cos(2nπ/3)/n = −(1/2)(H_{3M} − H_M) 的極限 = −(ln 3)/2。答案 = (3/4)(−(ln 3)/2) = −(3/8) ln 3 ≈ −0.4120。"],
