      prompt: "\\text{求 }1-2+3-4+\\cdots=\\sum_{n=0}^{\\infty}(-1)^n(n+1)\\text{ 的 Abel 和 }\\lim_{x\\to1^-}\\sum_{n=0}^{\\infty}(-1)^n(n+1)x^n",
      answer: "1/4",
