      solutionSteps: ["|x| < 1 時 Σ (−1)^n (n+1) x^n = 1/(1 + x)^2（把 Σ(n+1)y^n = 1/(1−y)^2 代 y = −x）。","x → 1^−：1/4。Abel 和 = 1/4。"],
