      solution: "Σ_{n≥0} C(n+2, 2) y^n = 1/(1 − y)^3（1/(1 − y) 微分兩次再除以 2）。代 y = −x：Σ (−1)^n C(n+2, 2) x^n = 1/(1 + x)^3，|x| < 1。x → 1^−：1/8。Abel 和 = 1/8。（部分和 1, −2, 4, −6, 9, … 振幅越來越大，連 Cesàro (C,1) 都不收斂。）",
      solutionSteps: ["Σ_{n≥0} C(n+2, 2) y^n = 1/(1 − y)^3（1/(1 − y) 微分兩次再除以 2）。","代 y = −x：Σ (−1)^n C(n+2, 2) x^n = 1/(1 + x)^3，|x| < 1。","x → 1^−：1/8。Abel 和 = 1/8。（部分和 1, −2, 4, −6, 9, … 振幅越來越大，連 Cesàro (C,1) 都不收斂。）"],
