      solutionSteps: ["Σ n cos(2nπ/3) x^n = Re Σ n (xω)^n = Re[xω/(1 − xω)^2]，ω = e^{2πi/3}。","x → 1：ω/(1 − ω)^2。1 − ω = −2i sin(π/3) e^{iπ/3}，(1 − ω)^2 = −4 sin^2(π/3) ω，所以 ω/(1 − ω)^2 = −1/(4 sin^2(π/3)) = −1/3。","Abel 和 = −1/3。（一般地 Σ n cos(nθ) 的 Abel 和 = −1/(4 sin^2(θ/2))。）"],
