      solutionSteps: ["S_{2k} = Σ_{j=1}^{k} ln((2j−1)/(2j)) → −∞ 很慢；S_{2k+1} = S_{2k} + ln(2k+1)。部分和的對平均 (S_{2k} + S_{2k+1})/2 = S_{2k} + (1/2)ln(2k+1)。","e^{S_{2k}}·√(2k+1) = [(1·3⋯(2k−1))/(2·4⋯2k)]·√(2k+1) → √(2/π)（Wallis）。","所以對平均 → (1/2) ln(2/π)；Cesàro 和存在則 Abel 和相同。答案 (1/2) ln(2/π) ≈ −0.2258。（等價說法：η′(0) = (1/2) ln(π/2)。）"],
