      solutionSteps: ["√[n]{a_n} = (2 + (−1)^n)/5：偶數 n 時 3/5，奇數 n 時 1/5。","limsup = 3/5 < 1，根值判別：Σ a_n 收斂。（極限本身不存在，這正是要用 limsup 的原因。）"],
