      solutionSteps: ["a_{n+1}/a_n = 2^{−1 + (−1)^{n+1} − (−1)^n} = 2^{−1 − 2(−1)^n}。","n 偶數：2^{−3} = 1/8；n 奇數：2^{1} = 2。","limsup = 2 > 1 而 liminf = 1/8 < 1，比值判別給不出結論；根值 √[n]{a_n} = 2^{−1 + (−1)^n/n} → 1/2，判定收斂。"],
